import{_ as t,o as a,c as o,ai as n}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/settings.md","filePath":"en/guide/settings.md"}'),l={name:"en/guide/settings.md"};function r(s,e,i,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>The Settings page lets you configure your Ollama connection, default model parameters, and application preferences.</p><p><strong>Sidebar item:</strong> Settings <strong>Route:</strong> <code>/settings</code></p><h2 id="connection" tabindex="-1">Connection <a class="header-anchor" href="#connection" aria-label="Permalink to &quot;Connection&quot;">​</a></h2><h3 id="ollama-url" tabindex="-1">Ollama URL <a class="header-anchor" href="#ollama-url" aria-label="Permalink to &quot;Ollama URL&quot;">​</a></h3><p>Set the URL where Ollama is running. Default: <code>http://localhost:11434</code>.</p><h3 id="connection-test" tabindex="-1">Connection Test <a class="header-anchor" href="#connection-test" aria-label="Permalink to &quot;Connection Test&quot;">​</a></h3><p>Click <strong>Test Connection</strong> to verify that LLMxRay can reach Ollama. The result shows:</p><ul><li><strong>Connected</strong> (green) — Ollama is reachable and responding</li><li><strong>Disconnected</strong> (red) — Check that <code>ollama serve</code> is running</li></ul><div class="tip custom-block"><p class="custom-block-title">Remote Ollama</p><p>If Ollama runs on another machine, enter its IP and port (e.g., <code>http://192.168.1.100:11434</code>). Make sure the Vite proxy is updated in <code>vite.config.ts</code> or that CORS is configured on the remote Ollama instance.</p></div><h2 id="default-parameters" tabindex="-1">Default Parameters <a class="header-anchor" href="#default-parameters" aria-label="Permalink to &quot;Default Parameters&quot;">​</a></h2><h3 id="temperature" tabindex="-1">Temperature <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Temperature&quot;">​</a></h3><p>Controls randomness in model outputs. Displayed with a <strong>visual scale</strong> and <strong>educational tooltip</strong>:</p><table tabindex="0"><thead><tr><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>Deterministic — always picks the most likely token</td></tr><tr><td><strong>0.7</strong></td><td>Balanced — default for most use cases</td></tr><tr><td><strong>1.0+</strong></td><td>Creative — more varied, sometimes surprising output</td></tr></tbody></table><h3 id="context-length" tabindex="-1">Context Length <a class="header-anchor" href="#context-length" aria-label="Permalink to &quot;Context Length&quot;">​</a></h3><p>Sets the maximum number of tokens the model considers. Higher values allow longer conversations but use more memory.</p><p>Both parameters include visual scales and plain-language explanations of what each setting does.</p><h2 id="model-catalog" tabindex="-1">Model Catalog <a class="header-anchor" href="#model-catalog" aria-label="Permalink to &quot;Model Catalog&quot;">​</a></h2><p>The Models tab (also accessible as a sidebar item) provides:</p><ul><li>A browsable catalog of installed models</li><li>Capability detection badges (thinking, vision, embedding, tool-use)</li><li>Architecture details and parameter counts</li><li>Comparison features for evaluating models side by side</li></ul><p>See the <a href="./models.html">Models</a> chapter for full details.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Toggle between:</p><ul><li><strong>Dark mode</strong> — Default, optimized for extended use</li><li><strong>Light mode</strong> — High-contrast alternative</li><li><strong>System</strong> — Follows your OS preference</li></ul><p>The theme toggle is also available in the header bar.</p><h2 id="google-oauth2" tabindex="-1">Google OAuth2 <a class="header-anchor" href="#google-oauth2" aria-label="Permalink to &quot;Google OAuth2&quot;">​</a></h2><p>For Tool Workshop templates that interact with Google services (Calendar, Gmail), you can configure OAuth2:</p><ol><li>Enter your <strong>Client ID</strong> from the Google Cloud Console</li><li>Click <strong>Connect</strong> to authorize</li><li>Once connected, Google-powered tools can access your account</li></ol><div class="warning custom-block"><p class="custom-block-title">Privacy</p><p>OAuth tokens are stored locally in your browser. LLMxRay never sends your credentials to any external server.</p></div><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Start with defaults</strong> — The default temperature (0.7) and context length work well for most models.</li><li><strong>Lower context length</strong> if you&#39;re running low on RAM/VRAM.</li><li>The connection tester is the fastest way to diagnose &quot;no models&quot; issues.</li></ul>',31)])])}const m=t(l,[["render",r]]);export{g as __pageData,m as default};
